function windChillF(T, v){
  if(v < 0) return NaN;
  if(v < 3) return T;
  return 35.74 + 0.6215*T - 35.75*Math.pow(v,0.16) + 0.4275*T*Math.pow(v,0.16);
}
function windChillC(Tc, v_kmh){
  var v_mph = v_kmh/1.609344;
  var Tf = Tc*9/5 + 32;
  return (windChillF(Tf, v_mph) - 32)*5/9;
}
var EXPORTS = { windChillF:windChillF, windChillC:windChillC };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WindChillForgePure = EXPORTS; }
